select rc.reconciliation_id, rc.decision_state, ro.evidence_side, ro.relationship, o.metric_id, o.reference_year, o.reported_value_numeric, o.reported_value_text, o.publication_status, o.visibility_scope from bse.bse_core_reconciliation_observation ro join bse.bse_core_reconciliation_case rc using(reconciliation_id) join bse.bse_core_observation o using(observation_id) order by rc.reconciliation_id
